for(let i=0;i<6;i++){const b=document.createElement('div');b.className='bubble';b.style.cssText=`left:${[27.6,34.7,30.9,71.2,75.4,71.2][i]}%;top:${[58.3,62,72.4,60.6,55.7,45.9][i]}%;--duration:${6+i*.7}s;--delay:-${i*1.3}s`;$('#bubbles').append(b)}let lastBubble=0;
window.addEventListener('pointermove',e=>{const now=performance.now();if(reduced||now-lastBubble<85||scrollY/innerHeight>5.9)return;lastBubble=now;const b=document.createElement('div');b.className='bubble trail';b.style.left=e.clientX+'px';b.style.top=e.clientY+'px';document.body.append(b);setTimeout(()=>b.remove(),3000)},{passive:true});
